(() => {
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const renderScript=p=>{
  const blocks=window.projectDocuments?.[p.documentKey||(p.id==='plumas'?'Plumas-羽毛制作者':p.title)];
  const content=blocks?blocks.map((b,i)=>b.kind==='table'?`<table class="script-table"><thead><tr>${(b.rows[0]||[]).map(c=>`<th scope="col" colspan="${c.span}">${esc(c.text)}</th>`).join('')}</tr></thead><tbody>${b.rows.slice(1).map(row=>`<tr>${row.map(c=>`<td colspan="${c.span}">${esc(c.text)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:b.kind==='heading'||i===0?`<h4 class="doc-heading">${esc(b.text)}</h4>`:`<p class="doc-paragraph">${esc(b.text)}</p>`).join(''):p.media.script.map(t=>`<p class="doc-paragraph">${esc(t)}</p>`).join('');
  return `<div class="script-toolbar"><span>保留表格结构，可左右滚动阅读</span><div role="group" aria-label="剧本字号"><button type="button" data-script-font="12" aria-pressed="false">小字</button><button type="button" data-script-font="13" aria-pressed="true">默认</button><button type="button" data-script-font="15" aria-pressed="false">大字</button></div></div><div class="script-text script-reader" tabindex="0" role="region" aria-label="剧本与分镜文字，可横向滚动">${content}</div>`;
 };
 const plumas={id:'plumas',type:'video',category:'short',tag:'短片',title:'Plumas · 羽毛制作者',bvid:'BV1ghyWzLEqG',cover:'assets/projects/plumas/cover.jpg',coverLabel:'作品封面',synopsis:'男孩把公鸡 Plumas 当作最好的朋友，父亲却要求它上场斗鸡。母亲为孩子争取童年的自由，让这对伙伴继续在游戏、电影与冒险幻想中相伴。',media:window.plumasMedia};
 window.portfolioProjects=[...window.localProjects,...window.designProjects];
 for(const p of window.portfolioProjects){if(p.id==='plumas')p.media=window.plumasMedia;}
 projects.splice(0,projects.length,...window.portfolioProjects);
 art=p=>`<div class="project-art plumas-cover"><img src="${esc(p.cover)}" alt="${esc(p.title+' '+p.coverLabel)}" loading="lazy"></div>`;
 renderGrid=(id,type='all',cat='all')=>{
  const list=projects.filter(p=>(type==='all'||p.type===type)&&(cat==='all'||p.category===cat||p.categories?.includes(cat)||cat==='game'&&p.category==='feed'||cat==='commercial'&&['tvc','seeding','feed'].includes(p.category)));
  document.getElementById(id).innerHTML=list.map(p=>p.type==='design'?`<article class="project-card real-project design-card">${art(p)}<div class="project-info"><div><h3>${esc(p.title)}</h3><p>VISUAL DESIGN · ${esc(p.tag)} · ${p.pageCount} 页</p></div></div><p class="card-synopsis">${esc(p.synopsis)}</p><div class="project-actions"><button class="button dark plant-control plant-process" data-project-open="${p.id}" data-mode="design">查看设计</button><a class="button" href="${esc(p.pdf)}" target="_blank" rel="noopener">阅读项目 PDF</a></div></article>`:`<article class="project-card real-project">${art(p)}<div class="project-info"><div><h3>${esc(p.title)}</h3><p>AI VIDEO · ${esc(p.tag)}</p></div></div><p class="card-synopsis">${esc(p.synopsis)}</p><div class="project-actions"><button class="button dark plant-control plant-watch" data-project-open="${p.id}" data-mode="watch">观看成片</button><button class="button plant-control plant-process" data-project-open="${p.id}" data-mode="process">查看制作过程</button></div></article>`).join('')||'<p class="empty">此分类暂未添加作品。<br>素材整理完成后将在这里展示。</p>';
 };
 const lightbox=document.createElement('dialog');lightbox.className='asset-lightbox';lightbox.setAttribute('aria-label','资产图片放大');lightbox.innerHTML='<button type="button" class="close" aria-label="关闭图片">×</button><img alt=""><p></p>';document.body.append(lightbox);
 lightbox.querySelector('button').onclick=()=>lightbox.close();lightbox.onclick=e=>{if(e.target===lightbox)lightbox.close()};
 const zoom=document.createElement('button');zoom.type='button';zoom.className='image-zoom';zoom.textContent='放大查看';lightbox.append(zoom);zoom.onclick=()=>{const active=lightbox.classList.toggle('is-zoomed');zoom.textContent=active?'适应屏幕':'放大查看';};
 const renderPlayer=p=>`<section id="finished-film"><h3>成片</h3><video class="local-player ${p.portrait?'is-portrait':''}" controls playsinline preload="metadata" poster="${esc(p.cover)}" src="${esc(p.video)}" aria-label="${esc(p.title)} 成片"></video><p class="playback-message" hidden>视频暂时无法加载，可以直接打开视频文件观看。</p><div class="project-actions"><a class="video-download" href="${esc(p.video)}" target="_blank" rel="noopener">打开视频文件</a>${p.bvid?`<a class="video-download" href="https://www.bilibili.com/video/${p.bvid}/" target="_blank" rel="noopener noreferrer">在 Bilibili 观看</a>`:''}</div></section>`;
 const gallery=items=>items.map(x=>`<button class="asset-thumb" data-full="${esc(x.src)}" data-caption="${esc(x.title)}"><img src="${esc(x.src)}" alt="${esc(x.title)}" loading="lazy" decoding="async"><span>${esc(x.title)}</span></button>`).join('');
 const renderDesign=p=>{
  dialog.setAttribute('aria-label',p.title);
  document.getElementById('dialog-content').innerHTML=`<span class="chip">VISUAL DESIGN / ${esc(p.tag)}</span><h2>${esc(p.title)}</h2><p class="design-intro">${esc(p.synopsis)}</p><div class="design-hero"><img src="${esc(p.cover)}" alt="${esc(p.title)}主视觉"></div><div class="project-actions"><a class="button dark" href="${esc(p.pdf)}" target="_blank" rel="noopener">阅读项目 PDF · ${p.pageCount} 页</a><a class="button" href="${esc(p.pdf)}" download>下载项目 PDF</a><a class="text-link" href="assets/design/complete-portfolio.pdf" target="_blank" rel="noopener">完整合集 · 94 页</a></div><nav class="design-section-nav" aria-label="项目内容分组">${p.sections.map((s,i)=>`<button type="button" data-design-section="design-section-${i}">${esc(s.title)}</button>`).join('')}</nav><p class="design-read-hint">按主题浏览，点击页面可放大阅读；PDF 保留完整原页内容。</p>${p.sections.map((s,i)=>`<section class="design-section" id="design-section-${i}"><h3>${esc(s.title)}</h3><div class="design-page-grid">${gallery(s.items)}</div></section>`).join('')}`;
  dialog.querySelectorAll('[data-design-section]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.designSection).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
  dialog.showModal();dialog.scrollTop=0;
 };
 document.addEventListener('click',e=>{
  const image=e.target.closest('[data-full]');if(image){lightbox.querySelector('img').src=image.dataset.full;lightbox.querySelector('img').alt=image.dataset.caption;lightbox.querySelector('p').textContent=image.dataset.caption;lightbox.classList.remove('is-zoomed');lightbox.querySelector('.image-zoom').textContent='放大查看';lightbox.showModal();return;}
  const font=e.target.closest('[data-script-font]');if(font){const details=font.closest('details');details.querySelector('.script-reader').style.setProperty('--script-font',font.dataset.scriptFont+'px');details.querySelectorAll('[data-script-font]').forEach(b=>b.setAttribute('aria-pressed',String(b===font)));return;}
  const trigger=e.target.closest('[data-project-open]');if(!trigger)return;
  const p=projects.find(p=>p.id===trigger.dataset.projectOpen);if(p.type==='design'){renderDesign(p);return;}const m=p.media;const groups=[...new Set(m.assets.map(x=>x.group))];
  dialog.setAttribute('aria-label',p.title);
  document.getElementById('dialog-content').innerHTML=`<span class="chip">VIDEO PROJECT / ${esc(p.tag)}</span><h2>${esc(p.title)}</h2><div class="project-actions"><button class="button dark plant-control plant-watch" data-section="finished-film">观看成片</button><button class="button plant-control plant-process" data-section="making-of">查看制作过程</button></div><section class="story-synopsis" aria-labelledby="synopsis-title"><span class="chip">${['tvc','seeding','feed'].includes(p.category)?'THE CONCEPT':'THE STORY'}</span><h3 id="synopsis-title">${['tvc','seeding','feed'].includes(p.category)?'内容梗概':'故事梗概'}</h3><p>${esc(p.synopsis)}</p></section>${renderPlayer(p)}<section class="responsibilities"><h3>个人职责</h3><p>待补充确认。</p></section><section id="making-of"><h3>制作过程</h3><p>制作资产共 ${m.assets.length} 张。点击分类展开，点击图片放大。</p>${groups.map((g,i)=>`<details class="asset-branch" ${i===0?'open':''}><summary>${esc(g.replace(/^\d+_/,''))}<span>${m.assets.filter(x=>x.group===g).length} 张</span></summary><div class="asset-grid">${gallery(m.assets.filter(x=>x.group===g))}</div></details>`).join('')}<h3>剧本与分镜</h3><div class="asset-grid">${gallery(m.storyboard)}</div><details><summary>阅读剧本与分镜文字</summary>${renderScript(p)}</details></section>`;
  const player=dialog.querySelector('.local-player');
  player.addEventListener('error',()=>{dialog.querySelector('.playback-message').hidden=false});
  player.addEventListener('loadedmetadata',()=>player.classList.toggle('is-portrait',player.videoHeight>player.videoWidth));
  document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.section).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
  dialog.showModal();dialog.scrollTop=0;if(trigger.dataset.mode==='process')requestAnimationFrame(()=>document.getElementById('making-of').scrollIntoView());
 });
 dialog.addEventListener('close',()=>{const player=dialog.querySelector('video');if(player){player.pause();player.removeAttribute('src');player.load();}});
 renderGrid('home-grid');if(document.getElementById('all-grid'))renderGrid('all-grid');
})();

